function bytesToBase64Url(bytes: Uint8Array): string {
  let binary = '';
  for (const b of bytes) binary += String.fromCharCode(b);
  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function base64UrlToBytes(value: string): Uint8Array {
  const padded = value.replace(/-/g, '+').replace(/_/g, '/');
  const padLen = (4 - (padded.length % 4)) % 4;
  const withPad = padded + '='.repeat(padLen);
  const binary = atob(withPad);
  const out = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) out[i] = binary.charCodeAt(i);
  return out;
}

export function parseCredentialsEncryptionKey(
  raw: string | undefined,
): Uint8Array | null {
  const trimmed = raw?.trim() ?? '';
  if (!trimmed) return null;

  if (/^[0-9a-fA-F]{64}$/.test(trimmed)) {
    const out = new Uint8Array(32);
    for (let i = 0; i < 32; i += 1) {
      out[i] = Number.parseInt(trimmed.slice(i * 2, i * 2 + 2), 16);
    }
    return out;
  }

  try {
    const decoded = base64UrlToBytes(trimmed);
    if (decoded.byteLength === 32) return decoded;
  } catch {
    // fall through
  }

  try {
    const binary = atob(trimmed);
    if (binary.length === 32) {
      const out = new Uint8Array(32);
      for (let i = 0; i < 32; i += 1) out[i] = binary.charCodeAt(i);
      return out;
    }
  } catch {
    // fall through
  }

  return null;
}

async function importAesKey(rawKey: Uint8Array): Promise<CryptoKey> {
  const keyBytes = new Uint8Array(rawKey);
  return crypto.subtle.importKey('raw', keyBytes, { name: 'AES-GCM' }, false, [
    'encrypt',
    'decrypt',
  ]);
}

export async function encryptProviderSecret(
  plaintext: string,
  rawKey: Uint8Array,
): Promise<string> {
  const key = await importAesKey(rawKey);
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const encoded = new TextEncoder().encode(plaintext);
  const cipherBuf = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, key, encoded);
  const cipher = new Uint8Array(cipherBuf);
  return `${PREFIX}.${bytesToBase64Url(iv)}.${bytesToBase64Url(cipher)}`;
}

export async function decryptProviderSecret(
  ciphertext: string,
  rawKey: Uint8Array,
): Promise<string> {
  const parts = ciphertext.split('.');
  if (parts.length !== 3 || parts[0] !== PREFIX) {
    throw new Error('CIPHER_FORMAT');
  }
  const iv = new Uint8Array(base64UrlToBytes(parts[1]));
  const data = new Uint8Array(base64UrlToBytes(parts[2]));
  const key = await importAesKey(rawKey);
  const plainBuf = await crypto.subtle.decrypt({ name: 'AES-GCM', iv }, key, data);
  return new TextDecoder().decode(plainBuf);
}

export function buildKeyHint(apiKey: string): string {
  const trimmed = apiKey.trim();
  const tail = trimmed.slice(-4);
  return `••••${tail}`;
}

export interface SupabaseServiceConfig {
  url: string;
  serviceRoleKey: string;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null;
}

export function hostAiProviderKeysAllowed(
  env: { get(key: string): string | undefined } = Deno.env,
): boolean {
  return env.get('AI_PROVIDER_ALLOW_HOST_KEYS') === '1';
}

export function resolveHostMeshyApiKey(
  env: { get(key: string): string | undefined } = Deno.env,
): string | null {
  if (!hostAiProviderKeysAllowed(env)) return null;
  const apiKey = env.get('MESHY_API_KEY')?.trim() ?? '';
  return apiKey || null;
}

async function loadEncryptedMeshySecret(
  config: SupabaseServiceConfig,
  userId: string,
): Promise<string | null> {
  const response = await fetch(
    `${config.url}/rest/v1/user_ai_provider_credentials?user_id=eq.${encodeURIComponent(userId)}&provider_id=eq.meshy&status=eq.active&select=secret_ciphertext&limit=1`,
    {
      headers: {
        Authorization: `Bearer ${config.serviceRoleKey}`,
        apikey: config.serviceRoleKey,
        Accept: 'application/json',
      },
      signal: AbortSignal.timeout(10_000),
    },
  );
  if (!response.ok) return null;
  const body: unknown = await response.json();
  if (!Array.isArray(body) || body.length === 0) return null;
  const row = body[0];
  if (!isRecord(row) || typeof row.secret_ciphertext !== 'string') return null;
  return row.secret_ciphertext;
}

export async function resolveMeshyApiKeyForUser(
  userId: string,
  config: SupabaseServiceConfig,
  env: { get(key: string): string | undefined } = Deno.env,
): Promise<string | null> {
  const encKey = parseCredentialsEncryptionKey(env.get('CREDENTIALS_ENCRYPTION_KEY'));
  if (encKey) {
    try {
      const ciphertext = await loadEncryptedMeshySecret(config, userId);
      if (ciphertext) {
        const plaintext = await decryptProviderSecret(ciphertext, encKey);
        if (plaintext.trim()) return plaintext.trim();
      }
    } catch (error) {
      console.error(
        'meshy user credential decrypt failed',
        error instanceof Error ? error.message : 'unknown',
      );
    }
  }

  return resolveHostMeshyApiKey(env);
}

export async function isMeshyConfiguredForUser(
  userId: string,
  config: SupabaseServiceConfig,
  env: { get(key: string): string | undefined } = Deno.env,
): Promise<boolean> {
  if (env.get('ITEM_THUMBNAIL_MESHY_MOCK') === '1' || env.get('ITEM_MODEL3D_MESHY_MOCK') === '1') {
    return true;
  }

  const response = await fetch(
    `${config.url}/rest/v1/user_ai_provider_credentials?user_id=eq.${encodeURIComponent(userId)}&provider_id=eq.meshy&status=eq.active&select=id&limit=1`,
    {
      headers: {
        Authorization: `Bearer ${config.serviceRoleKey}`,
        apikey: config.serviceRoleKey,
        Accept: 'application/json',
      },
      signal: AbortSignal.timeout(10_000),
    },
  );
  if (response.ok) {
    const body: unknown = await response.json();
    if (Array.isArray(body) && body.length > 0) return true;
  }

  return resolveHostMeshyApiKey(env) !== null;
}

export function findPrivilegedClientBodyKeys(
  body: unknown,
): PrivilegedClientBodyKey[] {
  if (body === null || typeof body !== 'object' || Array.isArray(body)) {
    return [];
  }
  const found: PrivilegedClientBodyKey[] = [];
  for (const key of Object.keys(body as Record<string, unknown>)) {
    if (PRIVILEGED.has(key)) {
      found.push(key as PrivilegedClientBodyKey);
    }
  }
  return found;
}

export function privilegedClientBodyRejectionMessage(
  body: unknown,
): string | null {
  const found = findPrivilegedClientBodyKeys(body);
  if (found.length === 0) return null;
  return `Client darf privilegierte Felder nicht setzen: ${found.join(', ')}`;
}

export type CorsOptions = {
  /** Override Allow-Methods (e.g. "POST, OPTIONS" for POST-only functions). */
  methods?: string;
  allowHeaders?: string;
  /**
   * Env keys tried in order for the allowlist CSV (or explicit `*`).
   * Default: CHARACTER_AI_ALLOWED_ORIGIN
   */
  envKeys?: string[];
  /** When true (default), include Content-Type: application/json on CORS header bags. */
  includeJsonContentType?: boolean;
  /**
   * When origin does not match allowlist/localhost:
   * - omit (default): do not set Access-Control-Allow-Origin (fail-closed)
   * - configured-or-star: set configured value or `*` (legacy meshy fallback)
   */
  missingOriginPolicy?: 'omit' | 'configured-or-star';
  /** When true, echo localhost even if an allowlist env is set (legacy meshy). */
  allowLocalhostWhenConfigured?: boolean;
};

function readConfiguredOrigin(envKeys: string[]): string {
  for (const key of envKeys) {
    const value = Deno.env.get(key)?.trim() ?? '';
    if (value) return value;
  }
  return '';
}

export function isLocalDevOrigin(origin: string): boolean {
  return /^https?:\/\/(localhost|127\.0\.0\.1)(:\d+)?$/i.test(origin);
}

export function corsHeaders(
  request: Request,
  opts: CorsOptions = {},
): Record<string, string> {
  const envKeys = opts.envKeys?.length
    ? opts.envKeys
    : ['CHARACTER_AI_ALLOWED_ORIGIN'];
  const configured = readConfiguredOrigin(envKeys);
  const requestOrigin = request.headers.get('Origin');
  const headers: Record<string, string> = {
    'Access-Control-Allow-Methods': opts.methods ?? DEFAULT_CORS_METHODS,
    'Access-Control-Allow-Headers':
      opts.allowHeaders ?? DEFAULT_CORS_ALLOW_HEADERS,
    Vary: 'Origin',
  };

  if (opts.includeJsonContentType !== false) {
    headers['Content-Type'] = 'application/json';
  }

  if (configured === '*') {
    headers['Access-Control-Allow-Origin'] = '*';
    return headers;
  }

  const allowlist = configured
    .split(',')
    .map((entry) => entry.trim())
    .filter(Boolean);

  if (requestOrigin && allowlist.includes(requestOrigin)) {
    headers['Access-Control-Allow-Origin'] = requestOrigin;
    return headers;
  }

  const localhostOk =
    Boolean(requestOrigin) &&
    isLocalDevOrigin(requestOrigin!) &&
    (!configured || opts.allowLocalhostWhenConfigured === true);

  if (localhostOk && requestOrigin) {
    headers['Access-Control-Allow-Origin'] = requestOrigin;
    return headers;
  }

  if (opts.missingOriginPolicy === 'configured-or-star') {
    headers['Access-Control-Allow-Origin'] = configured || '*';
  }

  return headers;
}

export function handleOptions(
  request: Request,
  opts?: CorsOptions,
): Response | null {
  if (request.method !== 'OPTIONS') return null;
  return new Response(null, {
    status: 204,
    headers: corsHeaders(request, opts),
  });
}

export function jsonResponse(
  request: Request,
  body: unknown,
  status = 200,
  opts?: CorsOptions,
): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: corsHeaders(request, opts),
  });
}

export function isAllowedItemThumbnailMime(value: string): value is ItemThumbnailMime {
  return (ITEM_THUMBNAIL_ALLOWED_MIME as readonly string[]).includes(value);
}

export function sniffItemThumbnailMime(bytes: Uint8Array): ItemThumbnailMime | null {
  if (
    bytes.length >= 8 &&
    bytes[0] === 0x89 &&
    bytes[1] === 0x50 &&
    bytes[2] === 0x4e &&
    bytes[3] === 0x47 &&
    bytes[4] === 0x0d &&
    bytes[5] === 0x0a &&
    bytes[6] === 0x1a &&
    bytes[7] === 0x0a
  ) {
    return 'image/png';
  }
  if (bytes.length >= 3 && bytes[0] === 0xff && bytes[1] === 0xd8 && bytes[2] === 0xff) {
    return 'image/jpeg';
  }
  // RIFF....WEBP
  if (
    bytes.length >= 12 &&
    bytes[0] === 0x52 &&
    bytes[1] === 0x49 &&
    bytes[2] === 0x46 &&
    bytes[3] === 0x46 &&
    bytes[8] === 0x57 &&
    bytes[9] === 0x45 &&
    bytes[10] === 0x42 &&
    bytes[11] === 0x50
  ) {
    return 'image/webp';
  }
  return null;
}

export function extensionForItemThumbnailMime(mime: ItemThumbnailMime): 'png' | 'jpg' | 'webp' {
  if (mime === 'image/png') return 'png';
  if (mime === 'image/webp') return 'webp';
  return 'jpg';
}

export function buildItemThumbnailStoragePath(options: {
  ownerUserId: string;
  definitionId: string;
  worldProfileId?: string | null;
  assetId: string;
  mime: ItemThumbnailMime;
}): string {
  const ext = extensionForItemThumbnailMime(options.mime);
  if (options.worldProfileId) {
    return `${options.ownerUserId}/world/${options.worldProfileId}/${options.definitionId}/${options.assetId}.${ext}`;
  }
  return `${options.ownerUserId}/${options.definitionId}/${options.assetId}.${ext}`;
}

export function buildItemThumbnailAssetKey(assetId: string): string {
  return `thumbnail2d:${assetId}`;
}

export function decodeBase64Image(contentBase64: string): Uint8Array {
  const cleaned = contentBase64.replace(/^data:image\/[a-zA-Z+]+;base64,/, '').trim();
  if (!cleaned) throw new Error('Empty image payload');
  const binary = atob(cleaned);
  if (binary.length > ITEM_THUMBNAIL_MAX_BYTES) {
    throw new Error('Image exceeds 10 MB limit');
  }
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}

export function validateThumbnailBytes(
  bytes: Uint8Array,
  claimedMime?: string,
): { mime: ItemThumbnailMime; bytes: Uint8Array } {
  if (bytes.byteLength === 0) throw new Error('Empty image');
  if (bytes.byteLength > ITEM_THUMBNAIL_MAX_BYTES) throw new Error('Image exceeds 10 MB limit');
  const sniffed = sniffItemThumbnailMime(bytes);
  if (!sniffed) throw new Error('Only PNG, JPEG and WebP images are allowed');
  if (claimedMime && claimedMime !== sniffed && !(claimedMime === 'image/jpg' && sniffed === 'image/jpeg')) {
    throw new Error('Declared MIME does not match file contents');
  }
  return { mime: sniffed, bytes };
}

function isAllowedMeshyHostname(hostname: string): boolean {
  const host = hostname.toLowerCase();
  return MESHY_HOST_ALLOWLIST.some(
    (allowed) => host === allowed || host.endsWith(`.${allowed}`),
  );
}

export async function downloadMeshyImageBytes(
  imageUrl: string,
  fetchImpl: typeof fetch = fetch,
): Promise<{ mime: ItemThumbnailMime; bytes: Uint8Array }> {
  let current = imageUrl;
  for (let hop = 0; hop < 3; hop += 1) {
    let parsed: URL;
    try {
      parsed = new URL(current);
    } catch {
      throw new Error('Invalid provider image URL');
    }
    if (parsed.protocol !== 'https:') throw new Error('Provider image URL must be HTTPS');
    if (!isAllowedMeshyHostname(parsed.hostname)) {
      throw new Error('Provider image host is not allowlisted');
    }

    const response = await fetchImpl(current, {
      method: 'GET',
      redirect: 'manual',
      signal: AbortSignal.timeout(20_000),
    });

    if (response.status >= 300 && response.status < 400) {
      const location = response.headers.get('Location');
      if (!location) throw new Error('Provider redirect without Location');
      current = new URL(location, parsed).toString();
      continue;
    }

    if (!response.ok) throw new Error(`Provider image download failed (${response.status})`);

    const contentLength = Number(response.headers.get('Content-Length') ?? '0');
    if (Number.isFinite(contentLength) && contentLength > ITEM_THUMBNAIL_MAX_BYTES) {
      throw new Error('Provider image exceeds size limit');
    }

    const buffer = new Uint8Array(await response.arrayBuffer());
    return validateThumbnailBytes(buffer);
  }

  throw new Error('Too many redirects while downloading provider image');
}

export interface MeshyTextToImageTask {
  id: string;
  status: MeshyTaskStatus;
  progress: number;
  image_urls?: string[];
  task_error?: { message?: string };
}

export interface MeshyProviderConfig {
  apiKey: string;
  baseUrl: string;
  model: string;
}

export interface MeshyTextToImageProvider {
  createTask(prompt: string): Promise<{ taskId: string }>;
  getTask(taskId: string): Promise<MeshyTextToImageTask>;
}

export function resolveMeshyProviderConfig(
  env: { get(key: string): string | undefined } = Deno.env,
  apiKeyOverride?: string | null,
): MeshyProviderConfig | null {
  const apiKey = apiKeyOverride !== undefined
    ? (apiKeyOverride?.trim() ?? '')
    : (env.get('MESHY_API_KEY')?.trim() ?? '');
  if (!apiKey) return null;

  const baseUrl = (env.get('MESHY_API_BASE_URL')?.trim() || DEFAULT_BASE).replace(/\/+$/, '');
  const model = env.get('MESHY_TEXT_TO_IMAGE_MODEL')?.trim() || DEFAULT_MODEL;

  return { apiKey, baseUrl, model };
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null;
}

function parseCreateResponse(body: unknown): string {
  if (!isRecord(body) || typeof body.result !== 'string' || !body.result.trim()) {
    throw new Error('Meshy create response missing result id');
  }
  return body.result.trim();
}

function parseTask(body: unknown): MeshyTextToImageTask {
  if (!isRecord(body) || typeof body.id !== 'string' || typeof body.status !== 'string') {
    throw new Error('Meshy task response invalid');
  }
  const status = body.status as MeshyTaskStatus;
  const progress = typeof body.progress === 'number' && Number.isFinite(body.progress)
    ? Math.max(0, Math.min(100, Math.round(body.progress)))
    : 0;
  const image_urls = Array.isArray(body.image_urls)
    ? body.image_urls.filter((u): u is string => typeof u === 'string' && u.startsWith('https://'))
    : undefined;
  const task_error = isRecord(body.task_error)
    ? { message: typeof body.task_error.message === 'string' ? body.task_error.message : undefined }
    : undefined;
  return { id: body.id, status, progress, image_urls, task_error };
}

export function createLiveMeshyProvider(
  config: MeshyProviderConfig,
  fetchImpl: FetchLike = fetch,
): MeshyTextToImageProvider {
  return {
    async createTask(prompt: string): Promise<{ taskId: string }> {
      const response = await fetchImpl(`${config.baseUrl}/text-to-image`, {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${config.apiKey}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          ai_model: config.model,
          prompt,
          aspect_ratio: '1:1',
        }),
        signal: AbortSignal.timeout(30_000),
      });

      if (response.status === 402) throw new Error('MESHY_CREDITS');
      if (response.status === 429) throw new Error('MESHY_RATE');
      if (!response.ok) throw new Error(`Meshy create failed (${response.status})`);

      const body: unknown = await response.json();
      return { taskId: parseCreateResponse(body) };
    },

    async getTask(taskId: string): Promise<MeshyTextToImageTask> {
      const response = await fetchImpl(`${config.baseUrl}/text-to-image/${encodeURIComponent(taskId)}`, {
        method: 'GET',
        headers: {
          Authorization: `Bearer ${config.apiKey}`,
          Accept: 'application/json',
        },
        signal: AbortSignal.timeout(20_000),
      });
      if (!response.ok) throw new Error(`Meshy status failed (${response.status})`);
      const body: unknown = await response.json();
      return parseTask(body);
    },
  };
}

export function createMockMeshyProvider(options?: {
  failCreate?: boolean;
  failStatus?: boolean;
  imageUrl?: string;
}): MeshyTextToImageProvider {
  const taskId = 'mock-meshy-task-001';
  let polls = 0;
  return {
    async createTask(_prompt: string): Promise<{ taskId: string }> {
      if (options?.failCreate) throw new Error('MESHY_CREDITS');
      return { taskId };
    },
    async getTask(id: string): Promise<MeshyTextToImageTask> {
      if (options?.failStatus) throw new Error('Meshy status failed (500)');
      polls += 1;
      if (polls < 2) {
        return { id, status: 'IN_PROGRESS', progress: 40 };
      }
      return {
        id,
        status: 'SUCCEEDED',
        progress: 100,
        image_urls: [options?.imageUrl ?? 'https://assets.meshy.ai/mock/output.png'],
      };
    },
  };
}

export function mapMeshyStatusToJob(status: MeshyTaskStatus): {
  status: 'waiting' | 'generating' | 'succeeded' | 'failed' | 'canceled';
  progress: number;
} {
  switch (status) {
    case 'PENDING':
      return { status: 'waiting', progress: 5 };
    case 'IN_PROGRESS':
      return { status: 'generating', progress: 50 };
    case 'SUCCEEDED':
      return { status: 'succeeded', progress: 100 };
    case 'CANCELED':
      return { status: 'canceled', progress: 0 };
    case 'FAILED':
    default:
      return { status: 'failed', progress: 0 };
  }
}

export interface ItemThumbnailPromptInput {
  name: string;
  description: string;
  setting?: string;
  kindKey?: string;
  userExtra?: string;
}

export function sanitizePromptPart(value: string, max: number): string {
  return value
    .replace(/[\r\n\t]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, max);
}

export function buildItemThumbnailPrompt(input: ItemThumbnailPromptInput): string {
  const name = sanitizePromptPart(input.name, 80) || 'item';
  const description = sanitizePromptPart(input.description, 220);
  const setting = sanitizePromptPart(input.setting ?? '', 60);
  const kind = sanitizePromptPart(input.kindKey ?? '', 40);
  const extra = sanitizePromptPart(input.userExtra ?? '', MAX_USER_EXTRA);

  const parts = [
    `Inventory icon of ${name}`,
    description ? `: ${description}` : '',
    kind ? `. Kind: ${kind}` : '',
    setting ? `. Setting: ${setting}` : '',
    extra ? `. Details: ${extra}` : '',
    `. Style: ${ART_DIRECTION}.`,
  ];

  return parts.join('').slice(0, MAX_PROMPT);
}

export function assertSafeUserExtra(raw: unknown): string {
  if (raw === undefined || raw === null || raw === '') return '';
  if (typeof raw !== 'string') throw new Error('userExtra must be a string');
  const cleaned = sanitizePromptPart(raw, MAX_USER_EXTRA);
  if (cleaned.length > MAX_USER_EXTRA) throw new Error('userExtra too long');
  return cleaned;
}

export interface ItemThumbnailRateLimitConfig {
  url: string;
  serviceRoleKey: string;
  limit: number;
  windowSeconds: number;
}

type FetchLike = (
  input: string | URL | Request,
  init?: RequestInit,
) => Promise<Response>;

export async function consumeItemThumbnailRateLimit(
  config: ItemThumbnailRateLimitConfig,
  userId: string,
  fetchImpl: FetchLike = fetch,
): Promise<boolean> {
  if (!userId.trim()) throw new Error('Rate limit user id is required');
  if (!Number.isInteger(config.limit) || config.limit < 1 || config.limit > 60) {
    throw new Error('Rate limit must be an integer between 1 and 60');
  }
  if (
    !Number.isInteger(config.windowSeconds) ||
    config.windowSeconds < 1 ||
    config.windowSeconds > 3600
  ) {
    throw new Error('Rate limit window must be an integer between 1 and 3600 seconds');
  }

  const response = await fetchImpl(`${config.url.replace(/\/+$/, '')}${RATE_LIMIT_RPC}`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.serviceRoleKey}`,
      apikey: config.serviceRoleKey,
      'Content-Type': 'application/json',
      Accept: 'application/json',
    },
    body: JSON.stringify({
      p_user_id: userId,
      p_limit: config.limit,
      p_window_seconds: config.windowSeconds,
    }),
    signal: AbortSignal.timeout(10_000),
  });

  if (!response.ok) {
    throw new Error(`Persistent rate limit RPC returned ${response.status}`);
  }

  const body: unknown = await response.json();
  if (typeof body !== 'boolean') {
    throw new Error('Persistent rate limit RPC returned an invalid response');
  }

  return body;
}

export type ServerProofStatus =
  | 'optimized'
  | 'unchanged'
  | 'unsupported'
  | 'over-budget'
  | 'failed';

export type ServerProofMetrics = {
  readonly inputBytes: number;
  readonly outputBytes: number;
  readonly width: number;
  readonly height: number;
  readonly decodeMs: number;
  readonly encodeMs: number;
  readonly totalMs: number;
  readonly rssDeltaBytes: number;
  readonly quality: number | null;
  /** PSNR (dB) of the encoded result vs. the (possibly scaled) decoded source; null if not encoded. */
  readonly psnrDb: number | null;
};

export type ServerProofResult = {
  readonly status: ServerProofStatus;
  readonly message: string;
  readonly output: Uint8Array | null;
  readonly metrics: ServerProofMetrics;
};

export type ServerProofOptions = {
  readonly maxEdge: number;
  readonly targetBytes: number;
};

type Raster = {
  readonly data: Uint8ClampedArray;
  readonly width: number;
  readonly height: number;
};

function toImageData(raster: Raster): ImageData {
  // Fresh ArrayBuffer-backed copy for Deno ImageData / jsquash encode typing.
  return new ImageData(new Uint8ClampedArray(raster.data), raster.width, raster.height);
}

export function readPngDimensions(bytes: Uint8Array): { width: number; height: number } | null {
  if (bytes.length < 24) return null;
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  return { width: view.getUint32(16), height: view.getUint32(20) };
}

function isGif(bytes: Uint8Array): boolean {
  return bytes.length >= 4 && bytes[0] === 0x47 && bytes[1] === 0x49 && bytes[2] === 0x46 && bytes[3] === 0x38;
}

async function decodeRaster(bytes: Uint8Array, mime: 'image/png' | 'image/jpeg' | 'image/webp'): Promise<Raster> {
  const buffer = bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength) as ArrayBuffer;
  const image =
    mime === 'image/png'
      ? await decodePng(buffer)
      : mime === 'image/jpeg'
        ? await decodeJpeg(buffer)
        : await decodeWebp(buffer);
  return {
    data: new Uint8ClampedArray(image.data),
    width: image.width,
    height: image.height,
  };
}

export function downscaleRaster(source: Raster, maxEdge: number): Raster {
  const longest = Math.max(source.width, source.height);
  if (longest <= maxEdge) return source;
  const scale = maxEdge / longest;
  const width = Math.max(1, Math.round(source.width * scale));
  const height = Math.max(1, Math.round(source.height * scale));
  const out = new Uint8ClampedArray(width * height * 4);
  for (let y = 0; y < height; y++) {
    const y0 = Math.floor((y * source.height) / height);
    const y1 = Math.max(y0 + 1, Math.floor(((y + 1) * source.height) / height));
    for (let x = 0; x < width; x++) {
      const x0 = Math.floor((x * source.width) / width);
      const x1 = Math.max(x0 + 1, Math.floor(((x + 1) * source.width) / width));
      let r = 0;
      let g = 0;
      let b = 0;
      let a = 0;
      let n = 0;
      for (let sy = y0; sy < y1; sy++) {
        for (let sx = x0; sx < x1; sx++) {
          const i = (sy * source.width + sx) * 4;
          r += source.data[i];
          g += source.data[i + 1];
          b += source.data[i + 2];
          a += source.data[i + 3];
          n++;
        }
      }
      const o = (y * width + x) * 4;
      out[o] = r / n;
      out[o + 1] = g / n;
      out[o + 2] = b / n;
      out[o + 3] = a / n;
    }
  }
  return { data: out, width, height };
}

export function psnrRgb(a: Raster, b: Raster): number {
  if (a.width !== b.width || a.height !== b.height) return Number.NaN;
  let sum = 0;
  const pixels = a.width * a.height;
  for (let p = 0; p < pixels; p++) {
    for (let c = 0; c < 3; c++) {
      const d = a.data[p * 4 + c] - b.data[p * 4 + c];
      sum += d * d;
    }
  }
  const mse = sum / (pixels * 3);
  return mse === 0 ? Number.POSITIVE_INFINITY : 10 * Math.log10((255 * 255) / mse);
}

function failure(
  status: Exclude<ServerProofStatus, 'optimized' | 'unchanged'>,
  message: string,
  partial: Partial<ServerProofMetrics>,
): ServerProofResult {
  return { status, message, output: null, metrics: { ...EMPTY_METRICS, ...partial } };
}

export async function optimizeRasterOnServerProof(
  input: Uint8Array,
  options: ServerProofOptions,
): Promise<ServerProofResult> {
  const startedAt = performance.now();
  const rssBefore = Deno.memoryUsage().rss;
  const base = { inputBytes: input.byteLength };

  if (input.byteLength === 0 || input.byteLength > SERVER_PROOF_MAX_INPUT_BYTES) {
    return failure('over-budget', 'Eingabegröße außerhalb des Serverbudgets.', base);
  }
  if (isGif(input)) {
    return failure('unsupported', 'GIF wird serverseitig nicht optimiert (Animation bliebe nicht erhalten).', base);
  }
  const mime = sniffItemThumbnailMime(input);
  if (!mime) {
    return failure('unsupported', 'Unbekanntes Bildformat (Magic Bytes).', base);
  }
  if (mime === 'image/png') {
    const dims = readPngDimensions(input);
    if (!dims || dims.width < 1 || dims.height < 1 || dims.width * dims.height > SERVER_PROOF_MAX_PIXELS) {
      return failure('over-budget', 'PNG-Abmessungen überschreiten das Pixelbudget.', base);
    }
  }

  try {
    const decodeStart = performance.now();
    const decoded = await decodeRaster(input, mime);
    const decodeMs = performance.now() - decodeStart;
    if (decoded.width * decoded.height > SERVER_PROOF_MAX_PIXELS) {
      return failure('over-budget', 'Bild überschreitet das Pixelbudget.', { ...base, decodeMs });
    }
    const source = downscaleRaster(decoded, options.maxEdge);
    const resized = source !== decoded;

    if (mime === 'image/webp' && !resized && input.byteLength <= options.targetBytes) {
      return {
        status: 'unchanged',
        message: 'WebP bereits innerhalb Budget.',
        output: input,
        metrics: {
          ...EMPTY_METRICS,
          ...base,
          outputBytes: input.byteLength,
          width: decoded.width,
          height: decoded.height,
          decodeMs,
          totalMs: performance.now() - startedAt,
        },
      };
    }

    const encodeStart = performance.now();
    let lastBytes = 0;
    for (const quality of SERVER_PROOF_QUALITY_LADDER) {
      const encoded = new Uint8Array(await encodeWebp(toImageData(source), { quality }));
      lastBytes = encoded.byteLength;
      if (encoded.byteLength <= options.targetBytes) {
        const encodeMs = performance.now() - encodeStart;
        const roundTrip = await decodeRaster(encoded, 'image/webp');
        return {
          status: 'optimized',
          message: 'Zu WebP optimiert.',
          output: encoded,
          metrics: {
            inputBytes: input.byteLength,
            outputBytes: encoded.byteLength,
            width: source.width,
            height: source.height,
            decodeMs,
            encodeMs,
            totalMs: performance.now() - startedAt,
            rssDeltaBytes: Deno.memoryUsage().rss - rssBefore,
            quality,
            psnrDb: psnrRgb(source, roundTrip),
          },
        };
      }
    }
    return failure('over-budget', 'Zielbytes auch bei niedrigster Qualität nicht erreichbar.', {
      ...base,
      outputBytes: lastBytes,
      width: source.width,
      height: source.height,
      decodeMs,
      encodeMs: performance.now() - encodeStart,
      totalMs: performance.now() - startedAt,
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Unbekannter Decode-/Encode-Fehler';
    console.error('[media-server-proof] decode/encode failed', message);
    return failure('failed', `Decode/Encode fehlgeschlagen: ${message}`, base);
  }
}

export function buildSyntheticRaster(width: number, height: number, withAlpha = false): Raster {
  const data = new Uint8ClampedArray(width * height * 4);
  let seed = 1234567;
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      seed = (seed * 1664525 + 1013904223) >>> 0;
      const noise = (seed >>> 24) % 24;
      const i = (y * width + x) * 4;
      data[i] = (x / width) * 200 + noise;
      data[i + 1] = (y / height) * 200 + noise;
      data[i + 2] = ((x + y) / (width + height)) * 255;
      data[i + 3] = withAlpha ? Math.round((x / width) * 255) : 255;
    }
  }
  return { data, width, height };
}

ITEM_THUMBNAIL_SERVER_OPTIMIZE: ServerProofOptions = {
  maxEdge: 1024,
  targetBytes: 1 * 1024 * 1024,
}

export type ProviderThumbnailOptimizeOk = {
  readonly ok: true;
  readonly mime: ItemThumbnailMime;
  readonly bytes: Uint8Array;
  readonly status: Extract<ServerProofStatus, 'optimized' | 'unchanged'>;
  readonly metrics: ServerProofResult['metrics'];
};

export type ProviderThumbnailOptimizeErr = {
  readonly ok: false;
  readonly status: Exclude<ServerProofStatus, 'optimized' | 'unchanged'>;
  readonly message: string;
  readonly metrics: ServerProofResult['metrics'];
};

export type ProviderThumbnailOptimizeResult =
  | ProviderThumbnailOptimizeOk
  | ProviderThumbnailOptimizeErr;

export async function optimizeProviderThumbnailBytes(
  input: Uint8Array,
  options: ServerProofOptions = ITEM_THUMBNAIL_SERVER_OPTIMIZE,
): Promise<ProviderThumbnailOptimizeResult> {
  const result = await optimizeRasterOnServerProof(input, options);

  if (result.metrics.totalMs > ITEM_THUMBNAIL_SERVER_OPTIMIZE_MAX_MS) {
    return {
      ok: false,
      status: 'failed',
      message: `Server-Optimierung überschritt das Zeitbudget (${ITEM_THUMBNAIL_SERVER_OPTIMIZE_MAX_MS} ms).`,
      metrics: result.metrics,
    };
  }

  if (result.status === 'optimized' || result.status === 'unchanged') {
    if (!result.output) {
      return {
        ok: false,
        status: 'failed',
        message: 'Optimierung lieferte kein Ausgabe-Byte.',
        metrics: result.metrics,
      };
    }
    try {
      const validated = validateThumbnailBytes(result.output);
      return {
        ok: true,
        mime: validated.mime,
        bytes: validated.bytes,
        status: result.status,
        metrics: result.metrics,
      };
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Nach-Encode-Validierung fehlgeschlagen';
      return {
        ok: false,
        status: 'failed',
        message,
        metrics: result.metrics,
      };
    }
  }

  return {
    ok: false,
    status: result.status,
    message: result.message,
    metrics: result.metrics,
  };
}

export function providerOptimizeFailureMessage(
  result: ProviderThumbnailOptimizeErr,
): string {
  return result.message || `Server-Optimierung fehlgeschlagen (${result.status}).`;
}

CORS_OPTS: CorsOptions = {
  methods: 'POST, OPTIONS',
  envKeys: [
    'ITEM_THUMBNAIL_ALLOWED_ORIGIN',
    'CHARACTER_AI_ALLOWED_ORIGIN',
  ],
}

interface SupabaseConfig {
  url: string;
  anonKey: string;
  serviceRoleKey: string;
}

interface DefinitionRow {
  id: string;
  scope: 'personal' | 'world';
  owner_user_id: string;
  world_profile_id: string | null;
  status: 'active' | 'archived';
  payload: JsonRecord;
}

function isRecord(value: unknown): value is JsonRecord {
  return typeof value === 'object' && value !== null;
}

function getCorsHeaders(request: Request): HeadersInit {
  return corsHeaders(request, CORS_OPTS);
}

function jsonResponse(request: Request, body: JsonRecord, status = 200): Response {
  return sharedJsonResponse(request, body, status, CORS_OPTS);
}

function getSupabaseConfig(): SupabaseConfig | null {
  const url = Deno.env.get('SUPABASE_URL')?.trim();
  const anonKey = Deno.env.get('SUPABASE_ANON_KEY')?.trim();
  const serviceRoleKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')?.trim();
  if (!url || !anonKey || !serviceRoleKey) return null;
  return { url: url.replace(/\/+$/, ''), anonKey, serviceRoleKey };
}

function getRateLimit(): number {
  const configured = Number.parseInt(Deno.env.get('ITEM_THUMBNAIL_RATE_LIMIT_PER_MINUTE') || '', 10);
  return Number.isFinite(configured) && configured > 0 ? Math.min(configured, 60) : DEFAULT_RATE_LIMIT;
}

async function resolveProvider(
  userId: string,
  supabaseConfig: SupabaseConfig,
): Promise<MeshyTextToImageProvider | null> {
  if (Deno.env.get('ITEM_THUMBNAIL_MESHY_MOCK') === '1') {
    return createMockMeshyProvider();
  }
  const apiKey = await resolveMeshyApiKeyForUser(userId, {
    url: supabaseConfig.url,
    serviceRoleKey: supabaseConfig.serviceRoleKey,
  });
  const config = resolveMeshyProviderConfig(Deno.env, apiKey);
  if (!config) return null;
  return createLiveMeshyProvider(config);
}

async function authenticate(request: Request, config: SupabaseConfig): Promise<string | null> {
  const authorization = request.headers.get('Authorization');
  if (!authorization?.startsWith('Bearer ')) return null;
  const response = await fetch(`${config.url}/auth/v1/user`, {
    headers: { Authorization: authorization, apikey: config.anonKey },
    signal: AbortSignal.timeout(10_000),
  });
  if (!response.ok) return null;
  const body: unknown = await response.json();
  return isRecord(body) && typeof body.id === 'string' ? body.id : null;
}

async function serviceFetch(
  config: SupabaseConfig,
  path: string,
  init?: RequestInit,
): Promise<Response> {
  return fetch(`${config.url}${path}`, {
    ...init,
    headers: {
      Authorization: `Bearer ${config.serviceRoleKey}`,
      apikey: config.serviceRoleKey,
      Accept: 'application/json',
      'Content-Type': 'application/json',
      ...(init?.headers ?? {}),
    },
    signal: AbortSignal.timeout(20_000),
  });
}

async function loadDefinition(
  config: SupabaseConfig,
  definitionId: string,
): Promise<DefinitionRow | null> {
  const response = await serviceFetch(
    config,
    `/rest/v1/inventory_item_definitions?select=id,scope,owner_user_id,world_profile_id,status,payload&id=eq.${encodeURIComponent(definitionId)}&limit=1`,
  );
  if (!response.ok) throw new Error(`Definition lookup failed (${response.status})`);
  const body: unknown = await response.json();
  const row = Array.isArray(body) ? body[0] : null;
  if (!isRecord(row)) return null;
  if (
    typeof row.id !== 'string' ||
    (row.scope !== 'personal' && row.scope !== 'world') ||
    typeof row.owner_user_id !== 'string' ||
    (row.status !== 'active' && row.status !== 'archived') ||
    !isRecord(row.payload)
  ) {
    return null;
  }
  return {
    id: row.id,
    scope: row.scope,
    owner_user_id: row.owner_user_id,
    world_profile_id: typeof row.world_profile_id === 'string' ? row.world_profile_id : null,
    status: row.status,
    payload: row.payload,
  };
}

async function canEditWorld(config: SupabaseConfig, userId: string, worldProfileId: string): Promise<boolean> {
  const response = await serviceFetch(
    config,
    `/rest/v1/world_profiles?select=id&id=eq.${encodeURIComponent(worldProfileId)}&owner_user_id=eq.${encodeURIComponent(userId)}&limit=1`,
  );
  if (!response.ok) return false;
  const body: unknown = await response.json();
  return Array.isArray(body) && body.length > 0;
}

async function assertCanMutateDefinition(
  config: SupabaseConfig,
  userId: string,
  definition: DefinitionRow,
): Promise<void> {
  if (definition.status !== 'active') throw new Error('DEFINITION_ARCHIVED');
  if (definition.scope === 'personal') {
    if (definition.owner_user_id !== userId) throw new Error('FORBIDDEN');
    return;
  }
  if (!definition.world_profile_id) throw new Error('FORBIDDEN');
  const ok = await canEditWorld(config, userId, definition.world_profile_id);
  if (!ok) throw new Error('FORBIDDEN');
}

async function assertCanReadAsset(
  config: SupabaseConfig,
  userId: string,
  ownerUserId: string,
  worldProfileId: string | null,
): Promise<boolean> {
  if (ownerUserId === userId) return true;
  if (!worldProfileId) return false;
  // World read: owner of world profile (same helper as edit for V1; broader read later)
  return canEditWorld(config, userId, worldProfileId);
}

async function uploadToStorage(
  config: SupabaseConfig,
  path: string,
  bytes: Uint8Array,
  mime: ItemThumbnailMime,
): Promise<void> {
  const payload = new Uint8Array(bytes.byteLength);
  payload.set(bytes);
  const response = await fetch(`${config.url}/storage/v1/object/${BUCKET}/${path}`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.serviceRoleKey}`,
      apikey: config.serviceRoleKey,
      'Content-Type': mime,
      'x-upsert': 'false',
    },
    body: payload,
    signal: AbortSignal.timeout(30_000),
  });
  if (!response.ok) {
    throw new Error(`Storage upload failed (${response.status})`);
  }
}

async function createSignedUrl(config: SupabaseConfig, path: string): Promise<string> {
  const response = await fetch(`${config.url}/storage/v1/object/sign/${BUCKET}/${path}`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.serviceRoleKey}`,
      apikey: config.serviceRoleKey,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ expiresIn: SIGNED_URL_SECONDS }),
    signal: AbortSignal.timeout(10_000),
  });
  if (!response.ok) throw new Error(`Signed URL failed (${response.status})`);
  const body: unknown = await response.json();
  if (!isRecord(body) || typeof body.signedURL !== 'string') {
    throw new Error('Signed URL response invalid');
  }
  const signed = body.signedURL.startsWith('http')
    ? body.signedURL
    : `${config.url}/storage/v1${body.signedURL}`;
  return signed;
}

async function softDeleteStorage(config: SupabaseConfig, path: string): Promise<void> {
  await fetch(`${config.url}/storage/v1/object/${BUCKET}`, {
    method: 'DELETE',
    headers: {
      Authorization: `Bearer ${config.serviceRoleKey}`,
      apikey: config.serviceRoleKey,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ prefixes: [path] }),
    signal: AbortSignal.timeout(10_000),
  }).catch(() => undefined);
}

async function insertAsset(
  config: SupabaseConfig,
  row: {
    id: string;
    definitionId: string;
    ownerUserId: string;
    worldProfileId: string | null;
    mime: ItemThumbnailMime;
    byteSize: number;
    storagePath: string;
    origin: 'upload' | 'meshy';
    providerTaskId?: string;
  },
): Promise<void> {
  const response = await serviceFetch(config, '/rest/v1/item_thumbnail_assets', {
    method: 'POST',
    headers: { Prefer: 'return=minimal' },
    body: JSON.stringify({
      id: row.id,
      kind: 'thumbnail2d',
      definition_id: row.definitionId,
      owner_user_id: row.ownerUserId,
      world_profile_id: row.worldProfileId,
      mime: row.mime,
      byte_size: row.byteSize,
      storage_path: row.storagePath,
      origin: row.origin,
      provider_task_id: row.providerTaskId ?? null,
    }),
  });
  if (!response.ok) throw new Error(`Asset insert failed (${response.status})`);
}

async function patchDefinitionAssetKey(
  config: SupabaseConfig,
  definition: DefinitionRow,
  assetKey: string | null,
): Promise<void> {
  const payload = { ...definition.payload };
  if (assetKey) payload.assetKey = assetKey;
  else delete payload.assetKey;

  const response = await serviceFetch(
    config,
    `/rest/v1/inventory_item_definitions?id=eq.${encodeURIComponent(definition.id)}`,
    {
      method: 'PATCH',
      headers: { Prefer: 'return=minimal' },
      body: JSON.stringify({ payload }),
    },
  );
  if (!response.ok) throw new Error(`Definition assetKey update failed (${response.status})`);
}
